SELECT COUNT(*) AS order_count
FROM orders
WHERE order_purchase_timestamp >= (
    SELECT MAX(order_purchase_timestamp)::date - INTERVAL '89 days'
    FROM orders
  )
  AND order_purchase_timestamp < (
    SELECT MAX(order_purchase_timestamp)::date + INTERVAL '1 day'
    FROM orders
  );

