SELECT COUNT(*) AS late_order_count
FROM orders
WHERE order_delivered_customer_date > order_estimated_delivery_date;

SELECT ROUND(COUNT(*) FILTER (
    WHERE o.order_delivered_customer_date IS NOT NULL
      AND o.order_delivered_customer_date > o.order_estimated_delivery_date
)::numeric / NULLIF(COUNT(*) FILTER (
    WHERE o.order_delivered_customer_date IS NOT NULL
), 0), 4) AS late_delivery_rate
FROM orders o;

SELECT ROUND(AVG(EXTRACT(EPOCH FROM (resolved_at - created_at)) / 3600.0)::numeric, 2) AS avg_resolution_hours
FROM support_tickets
WHERE resolved_at IS NOT NULL;

SELECT ROUND(
  COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM refunds r WHERE r.order_id = o.order_id))::numeric
  / NULLIF(COUNT(*), 0),
  4
) AS refund_order_ratio
FROM orders o;
